package events

import (
	"bufio"
	"os"
	"strings"
	"testing"

	"github.com/developmi/caddy-waf-ui/internal/crs"
)

// The fixture was recorded from Caddy 2.11.6 + coraza-caddy v2.6.1 +
// Coraza v3.8.0 + CRS 4.25.0 (the versions of liukan/caddy-with-auth)
// with an overlay generated by this UI: DetectionOnly with tuning mode and
// detection PL 2 for the first six requests, then On.
func loadFixture(t *testing.T) []*Event {
	t.Helper()
	f, err := os.Open("testdata/coraza-3.8.0-audit.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = f.Close() }()
	n := &Normalizer{Dict: crs.Default(), Node: "test"}
	var out []*Event
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 4<<20)
	for scanner.Scan() {
		e, err := n.Normalize(scanner.Bytes())
		if err != nil {
			t.Fatal(err)
		}
		out = append(out, e)
	}
	if len(out) != 9 {
		t.Fatalf("expected 9 fixture records, got %d", len(out))
	}
	return out
}

func hitIDs(e *Event) []int {
	var ids []int
	for _, h := range e.Hits {
		ids = append(ids, h.ID)
	}
	return ids
}

func TestNormalizeDetectionOnlyDecision(t *testing.T) {
	e := loadFixture(t)[0]
	if e.Path != "/.git/config" || e.Site != "example.com" || e.Host != "example.com" || e.Method != "GET" {
		t.Fatalf("request fields: %+v", e)
	}
	if e.Action != ActionWouldBlock || e.Interrupted || e.Engine != "DetectionOnly" {
		t.Fatalf("a DetectionOnly decision must be would_block: %+v", e)
	}
	if e.BlockingPL != 1 || e.DetectionPL != 2 || e.ThrIn != 5 || !e.Tuning || e.Revision == "" || e.Mode != "DetectionOnly" {
		t.Fatalf("policy signature not decoded: %+v", e)
	}
	if e.CRS != "4.25.0" || e.RuleIDs != ",930130,949110," {
		t.Fatalf("crs/rule ids: %q %q", e.CRS, e.RuleIDs)
	}
	h := e.Hits[0]
	if h.Kind != crs.KindDetection || h.Score != 5 || h.PL != 1 || h.Var != "REQUEST_FILENAME" || h.Data != ".git/" || h.Severity != "CRITICAL" || h.Category != "lfi" {
		t.Fatalf("930130 hit: %+v", h)
	}
	if e.Hits[1].Kind != crs.KindDecision || e.Hits[1].Severity != "" {
		t.Fatalf("949110 hit: %+v", e.Hits[1])
	}
	if e.ScoreIn != 5 || e.ReportedIn != 5 {
		t.Fatalf("recomputed %d vs reported %d", e.ScoreIn, e.ReportedIn)
	}
	if e.TS.Year() != 2026 || e.TS.Location().String() != "UTC" {
		t.Fatalf("timestamp: %v", e.TS)
	}
}

func TestNormalizeChainContinuationsAndParanoiaLevels(t *testing.T) {
	e := loadFixture(t)[1]
	count := map[int]int{}
	for _, id := range hitIDs(e) {
		count[id]++
	}
	if count[932240] != 1 || count[942130] != 1 {
		t.Fatalf("chain continuation messages must not become hits: %v", hitIDs(e))
	}
	// Only 942100 is PL1: the blocking score equals Coraza's reported total.
	if e.ScoreIn != 5 || e.ReportedIn != 5 || e.DetectIn <= e.ScoreIn {
		t.Fatalf("scores: in=%d reported=%d detect=%d", e.ScoreIn, e.ReportedIn, e.DetectIn)
	}
	if len(e.QueryKeys) != 1 || e.QueryKeys[0] != "r" || strings.Contains(e.Path, "?") {
		t.Fatalf("query keys only, no values: %q %v", e.Path, e.QueryKeys)
	}
}

func TestNormalizeSubThresholdTuningRecord(t *testing.T) {
	e := loadFixture(t)[2]
	if e.Action != ActionDetected || e.ScoreIn != 0 || len(e.Hits) != 1 {
		t.Fatalf("sub-threshold record: %+v", e)
	}
	if h := e.Hits[0]; h.ID != 920320 || h.PL != 2 || h.Severity != "NOTICE" || h.Score != 2 {
		t.Fatalf("920320: %+v", h)
	}
}

func TestNormalizeRedactsCredentials(t *testing.T) {
	cookie := loadFixture(t)[3]
	for _, h := range cookie.Hits {
		if h.Kind == crs.KindDecision {
			continue
		}
		if !strings.HasPrefix(h.Var, "REQUEST_COOKIES:") || h.Data != redacted || h.Value != redacted {
			t.Fatalf("cookie match must be redacted: %+v", h)
		}
	}
	chat := loadFixture(t)[5]
	sawPassword, sawContent := false, false
	for _, h := range chat.Hits {
		switch h.Var {
		case "ARGS:json.password":
			sawPassword = true
			if h.Data != redacted || h.Value != redacted {
				t.Fatalf("password-like JSON key must be redacted: %+v", h)
			}
		case "ARGS:json.messages.0.content":
			sawContent = true
			if h.Data == redacted {
				t.Fatalf("ordinary content must stay visible for tuning: %+v", h)
			}
		}
	}
	if !sawPassword || !sawContent {
		t.Fatalf("expected both JSON keys: %+v", chat.Hits)
	}
}

func TestNormalizeMultiMatchScoresPerVariable(t *testing.T) {
	e := loadFixture(t)[4]
	if e.ScoreIn != 30 || e.ReportedIn != 30 {
		t.Fatalf("each matched variable adds its score: in=%d reported=%d", e.ScoreIn, e.ReportedIn)
	}
}

func TestNormalizeBlockedRecords(t *testing.T) {
	events := loadFixture(t)
	if e := events[6]; e.Action != ActionBlocked || !e.Interrupted || e.Mode != "On" {
		t.Fatalf("On-mode decision: %+v", e)
	}
	broken := events[7]
	if broken.Action != ActionBlocked || broken.Hits[0].ID != 200002 || broken.Hits[0].Kind != crs.KindBlocking {
		t.Fatalf("direct block: %+v", broken)
	}
	scanner := events[8]
	if scanner.Hits[0].ID != 913100 || scanner.Hits[0].Category != "reputation-scanner" || len(scanner.QueryKeys) != 1 {
		t.Fatalf("scanner: %+v", scanner)
	}
}

func TestNormalizeWithoutSignatureUsesHostMapping(t *testing.T) {
	raw := `{"transaction":{"unix_timestamp":1791242354095684000,"id":"legacy-1","client_ip":"192.0.2.9",` +
		`"server_id":"www.example.com:8443","request":{"method":"POST","uri":"/login?next=%2F"},"is_interrupted":true},` +
		`"messages":[{"actionset":"OWASP_CRS/4.25.0","data":{"id":942100,"msg":"SQL Injection Attack Detected via libinjection",` +
		`"data":"Matched Data: s&1 found within ARGS:user: x' or 1=1","severity":2,"tags":["paranoia-level/1"]}}]}`
	n := &Normalizer{Dict: crs.Default(), SiteForHost: func(host string) string {
		if host == "www.example.com" {
			return "example.com"
		}
		return ""
	}}
	e, err := n.Normalize([]byte(raw))
	if err != nil {
		t.Fatal(err)
	}
	if e.Site != "example.com" || e.Host != "www.example.com" || e.Action != ActionBlocked || e.ScoreIn != 5 {
		t.Fatalf("legacy record: %+v", e)
	}
	if _, err := n.Normalize([]byte(`{"transaction":{}}`)); err == nil {
		t.Fatal("records without a transaction id must be rejected")
	}
}

func TestSplitLogdata(t *testing.T) {
	cases := []struct{ in, v, d, val string }{
		{"Matched Data: .env found within REQUEST_FILENAME: /.env", "REQUEST_FILENAME", ".env", "/.env"},
		{"Matched Data: x found within ARGS:json.a.b: y found within ARGS:z: w", "ARGS:json.a.b", "x", "y found within ARGS:z: w"},
		{"Restricted header detected: /proxy/", "", "Restricted header detected: /proxy/", ""},
		{"", "", "", ""},
	}
	for _, c := range cases {
		v, d, val := splitLogdata(c.in)
		if v != c.v || d != c.d || val != c.val {
			t.Errorf("splitLogdata(%q) = %q %q %q", c.in, v, d, val)
		}
	}
	if got := truncate(strings.Repeat("中", 100), 10); !strings.HasSuffix(got, "…") || len(got) > 13 {
		t.Fatalf("truncate must respect UTF-8: %q", got)
	}
}
